module protocol::reserve;

use sui::balance::{Self, Balance, Supply};
use sui::coin::{Coin};
use sui::dynamic_field;

use protocol::ctoken::CToken;
use protocol::error;
use protocol::ctoken;
use math::float::{Self, Decimal};
use protocol::borrow_index::{Self, BorrowIndex};

public struct Reserve<phantom MarketType> has key, store {
    id: UID,

    debt: Decimal,
    cash_reserve: Decimal,

    // cash equals to ReserveBalance.underlying_balance, it is required as util_rate requires query without generic type
    cash: u64,
    // total_suppy equals to ReserveBalance.ctoken_supply.supply_value, it is required as exchange_rate requires query without generic type
    total_supply: u64,

    borrow_index: BorrowIndex,
}

public struct ReserveBalanceKey has copy, drop, store {} 
public struct ReserveBalance<phantom MarketType, phantom CoinType> has store {
    underlying_balance: Balance<CoinType>,
    ctoken_supply: Supply<CToken<MarketType, CoinType>>,
}

public struct ReserveFlashLoan<phantom MarketType, phantom CoinType> {
    amount: u64,
}

// create a vault for storing underlying assets and market coin supplies
public(package) fun new<MarketType, CoinType>(ctx: &mut TxContext, now: u64): Reserve<MarketType> {
    let mut reserve = Reserve {
        id: object::new(ctx),
        cash: 0,
        debt: float::zero(),
        cash_reserve: float::zero(),
        total_supply: 0,

        borrow_index: borrow_index::new(now),
    };

    dynamic_field::add(
        &mut reserve.id,
        ReserveBalanceKey {},
        ReserveBalance<MarketType, CoinType> {
            underlying_balance: balance::zero<CoinType>(),
            ctoken_supply: balance::create_supply(ctoken::new()),
        }
    );

    reserve
}

public(package) fun debt<MarketType>(self: &Reserve<MarketType>): &Decimal { &self.debt }

public(package) fun borrow_index<MarketType>(self: &Reserve<MarketType>): &BorrowIndex { &self.borrow_index }

public(package) fun util_rate<MarketType>(self: &Reserve<MarketType>): Decimal {
    if (self.debt.is_zero()) {
        return float::from_quotient(0, 1)
    };

    let denominator = self.cash_plus_borrows_minus_reserves();
    self.debt.div(denominator)
}

public(package) fun cash_plus_borrows_minus_reserves<MarketType,>(self: &Reserve<MarketType>): Decimal {
    self.debt.add_u64(self.cash).sub(self.cash_reserve)
}

public(package) fun protocol_reserve<MarketType>(self: &Reserve<MarketType>): u64 {
    self.cash_reserve.floor()
}

public(package) fun total_deposit_plus_interest<MarketType,>(self: &Reserve<MarketType>): Decimal {
    self.exchange_rate().mul_u64(self.total_supply)
}

/// Caller should ensure this asset can be collateral
public(package) fun deposit_limit_breached<MarketType>(self: &Reserve<MarketType>, increment: u64, limit: u64): bool {
    let total_deposit_plus_interest = self.total_deposit_plus_interest();
    total_deposit_plus_interest.ceil() + increment - self.cash_reserve.ceil() > limit
}

public(package) fun exchange_rate<MarketType>(self: &Reserve<MarketType>): Decimal {
    if (self.total_supply == 0) {
        return float::from_quotient(1, 1)
    };

    let numerator = self.cash_plus_borrows_minus_reserves();
    let denominator = float::from(self.total_supply);

    numerator.div(denominator)
}

