    let amount = 10000;
    let borrowed_balance = reserve.borrow_amount<MainMarket, BTC>(amount);

    let reserve_factor = float::from_quotient(1, 100);
    // 5% per year
    let interest_rate = math::float::from_quotient(158548959918, 1000000000000000000);
    let time = 1000; // 1000 seconds
    reserve.accrue_interest(reserve_factor, interest_rate, time);

    let expected_interest = float::from_quotient(1585489599180000000, 1000000000000000000);
    let expected_debt = float::from(amount).add(expected_interest);

    assert!(reserve.debt.eq(expected_debt));
    // 1 comes from interest
    assert!(reserve.debt.floor() == amount + 1);
    let repay_btc = sui::balance::create_for_testing<BTC>(reserve.debt.floor()).into_coin(ctx);
    reserve.repay_amount<MainMarket, BTC>(repay_btc);

    // sub 1 because repaid 1 interest
    assert!(reserve.debt.eq(expected_interest.sub(float::one())));
    assert!(reserve.cash == base + 1);

